        r = rank(vandermonde(nodes, exps))
        print(f"     n={n}, b={b}: (b+1)^n = {(b+1)**n:>3}, rank = {r:>3}"
              f"  -> {'isomorphism' if r == (b+1)**n else 'FAILS'}")
        assert r == (b + 1) ** n


